from toolz.curried import partition_all as curried_partition_all
from toolz import partition_all

# list subclass with lying __len__
class BadList(list):
    def __len__(self):
        return 3
try:
    list(partition_all(2, BadList([1,2,3,4,5])))
    print('FAIL: no error')
except LookupError:
    print('OK: BadList raises LookupError')

# curried, partially applied, buggy input
try:
    list(curried_partition_all(2)(BadList([1,2,3,4,5])))
    print('FAIL: curried no error')
except LookupError:
    print('OK: curried raises LookupError')

# tuple subclass with lying __len__ (true 5, n=3, fake 4 -> remainder 1 vs true 2)
class BadTuple(tuple):
    def __len__(self):
        return 4
try:
    list(partition_all(3, BadTuple((1,2,3,4,5))))
    print('FAIL: tuple no error')
except LookupError:
    print('OK: BadTuple raises LookupError')

# correct tuple subclass still works
class GoodTuple(tuple):
    pass
print('OK correct tuple:', list(partition_all(3, GoodTuple((1,2,3,4,5)))))

# a string (correct __len__) still works
print('OK string:', list(partition_all(3, 'abcde')))
"

